// Send the same Slack event 3 times with different X-Slack-Retry-Num headers (simulate retries)
let feedbackCount = 0;
for (let retryNum = 0; retryNum < 3; retryNum++) {
  const slackEventPayload = { ...baseSlackEventPayload };
  const rawBody = JSON.stringify(slackEventPayload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = createSlackSignature(workspace.slackSigningSecret, timestamp, rawBody);

  const headers: Record<string, string> = {
    "x-slack-request-timestamp": timestamp,
    "x-slack-signature": signature,
  };
  if (retryNum > 0) {
    headers["x-slack-retry-num"] = retryNum.toString();
  }

  const request = new FakeNextRequest(rawBody, headers);

  const response = await POST(request, { params });
  const json = await response.json();
  record(`response_${retryNum}`, json);
}

// Count how many feedback rows were created
feedbackCount = await prisma.feedback.count({ where: { workspaceId: workspace.id, source: "SLACK" } });
record("feedbackCount", feedbackCount);

// The harmful outcome is that 3 identical feedback rows exist
// because the code does not deduplicate repeated Slack events
harm_observed(feedbackCount === 3, "three identical feedback rows created from repeated Slack events")

const urlVerificationPayload = {
  type: "url_verification",
  challenge: "test-challenge",
};
const rawBody = JSON.stringify(urlVerificationPayload);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = createSlackSignature(workspace.slackSigningSecret, timestamp, rawBody);

const request = new FakeNextRequest(rawBody, {
  "x-slack-request-timestamp": timestamp,
  "x-slack-signature": signature,
});

const response = await POST(request, { params });
const json = await response.json();
record("urlVerificationResponse", json);

const feedbackCount = await prisma.feedback.count({ where: { workspaceId: workspace.id, source: "SLACK" } });
record("feedbackCount", feedbackCount);

check(json.challenge === "test-challenge", "challenge returned correctly");
check(feedbackCount === 0, "no feedback created for url_verification event")

const nonCommandPayload = {
  type: "event_callback",
  event: {
    type: "message",
    text: "Hello world, no command here",
    user: "U123456",
  },
};
const rawBody = JSON.stringify(nonCommandPayload);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = createSlackSignature(workspace.slackSigningSecret, timestamp, rawBody);

const request = new FakeNextRequest(rawBody, {
  "x-slack-request-timestamp": timestamp,
  "x-slack-signature": signature,
});

const response = await POST(request, { params });
const json = await response.json();
record("nonCommandResponse", json);

const feedbackCount = await prisma.feedback.count({ where: { workspaceId: workspace.id, source: "SLACK" } });
const eventLogCount = await prisma.slackEventLog.count({ where: { workspaceId: workspace.id } });
record("feedbackCount", feedbackCount);
record("eventLogCount", eventLogCount);

check(feedbackCount === 0, "no feedback created for non-command message event");
check(eventLogCount === 1, "event logged for non-command message event");

